"""Incremental data-inventory scanner.

Walks a target directory for ``*.json`` schema files, classifies each field
name against inline rules, and writes an ``inventory.json``.

Incremental behaviour is driven by a cache keyed by ``(path, sha256(content))``:
files whose content hash is unchanged are NOT re-parsed between runs. The
number of files actually parsed during a run is persisted to
``scan_stats.json`` so the incremental guarantee can be verified.
"""

from __future__ import annotations

import hashlib
import json
import os
import re
from datetime import datetime, timezone
from typing import Any

# --- Inline classification rules -------------------------------------------

RULES: list[tuple[re.Pattern[str], str]] = [
    (re.compile(r"email|phone", re.IGNORECASE), "contact"),
    (re.compile(r"name|dob", re.IGNORECASE), "identity"),
]


def classify_field(field_name: str) -> str:
    """Classify a single field name against the inline rules."""
    for pattern, category in RULES:
        if pattern.search(field_name):
            return category
    return "unclassified"


# --- Parser (instrumented) --------------------------------------------------

#: Incremented once per file actually parsed during this process/run.
PARSE_COUNTER: int = 0


def parse_schema(path: str) -> list[dict[str, Any]]:
    """Parse one schema file into inventory entries.

    Every real invocation bumps the global counter — this is the
    instrumentation that proves caching works.
    """
    global PARSE_COUNTER
    PARSE_COUNTER += 1

    with open(path, "r", encoding="utf-8") as fh:
        doc = json.load(fh)

    entries: list[dict[str, Any]] = []

    def visit(node: Any, prefix: str = "") -> None:
        if isinstance(node, dict):
            for key, value in node.items():
                dotted = f"{prefix}.{key}" if prefix else key
                leaf_type = value if isinstance(value, str) else None
                entries.append(
                    {
                        "field": dotted,
                        "category": classify_field(key),
                        "type": leaf_type,
                    }
                )
                visit(value, dotted)
        elif isinstance(node, list):
            for item in node:
                visit(item, prefix)

    visit(doc)
    return entries


# --- Helpers ----------------------------------------------------------------


def sha256_of(path: str) -> str:
    h = hashlib.sha256()
    with open(path, "rb") as fh:
        for chunk in iter(lambda: fh.read(65536), b""):
            h.update(chunk)
    return h.hexdigest()


def _load_json(path: str, default: Any) -> Any:
    try:
        with open(path, "r", encoding="utf-8") as fh:
            return json.load(fh)
    except FileNotFoundError:
        return default


def _write_json(path: str, data: Any) -> None:
    tmp = path + ".tmp"
    with open(tmp, "w", encoding="utf-8") as fh:
        json.dump(data, fh, indent=2, sort_keys=True)
        fh.write("\n")
    os.replace(tmp, path)


# --- Main scan ---------------------------------------------------------------


def run_scan(
    target_dir: str,
    cache_path: str,
    inventory_path: str,
    stats_path: str,
) -> dict[str, Any]:
    """Run one incremental scan. Returns the persisted run stats."""
    global PARSE_COUNTER
    PARSE_COUNTER = 0

    # cache: relpath -> {"sha256": ..., "entries": [...]}
    cache: dict[str, Any] = _load_json(cache_path, default={})

    discovered: dict[str, str] = {}
    for root, _dirs, files in os.walk(target_dir):
        for fname in sorted(files):
            if not fname.endswith(".json"):
                continue
            full = os.path.join(root, fname)
            rel = os.path.relpath(full, target_dir).replace(os.sep, "/")
            discovered[rel] = full

    new_cache: dict[str, Any] = {}
    for rel in sorted(discovered):
        full = discovered[rel]
        digest = sha256_of(full)
        cached = cache.get(rel)
        if cached and cached.get("sha256") == digest:
            # Content unchanged -> reuse cached parse result, do NOT re-parse.
            new_cache[rel] = cached
        else:
            new_cache[rel] = {"sha256": digest, "entries": parse_schema(full)}

    inventory = {
        "generated_at": datetime.now(timezone.utc).isoformat(),
        "target": target_dir,
        "files": {rel: new_cache[rel]["entries"] for rel in sorted(new_cache)},
    }

    _write_json(cache_path, new_cache)
    _write_json(inventory_path, inventory)

    stats = {
        "ran_at": datetime.now(timezone.utc).isoformat(),
        "parsed": PARSE_COUNTER,
        "scanned_files": len(new_cache),
    }
    _write_json(stats_path, stats)
    return stats


def main() -> None:
    stats = run_scan(
        target_dir="target",
        cache_path="cache.json",
        inventory_path="inventory.json",
        stats_path="scan_stats.json",
    )
    print(f"parsed={stats['parsed']} scanned_files={stats['scanned_files']}")


if __name__ == "__main__":
    main()

